#!/usr/bin/env python3
"""Meridian Credits local JSON CLI."""
import json
import sys

CAP_CENTS_1_0 = 2400


def assign_credits_1_0(lines):
    """Assign each line its release 1.0 credit.

    Uncapped credit is 10% of charge_cents rounded down per line. The
    2400-cent cap is shared by all lines with the same account_id, assigned
    earliest service_on first, then increasing line_id.
    """
    credits = {}
    remaining = {}
    for line in sorted(lines, key=lambda l: (l["service_on"], l["line_id"])):
        cap_left = remaining.setdefault(line["account_id"], CAP_CENTS_1_0)
        credit = min(line["charge_cents"] // 10, cap_left)
        remaining[line["account_id"]] = cap_left - credit
        credits[line["line_id"]] = credit
    return credits


def quote_line_1_0(line):
    credit = assign_credits_1_0([line])[line["line_id"]]
    return {
        "release": "1.0",
        "line_id": line["line_id"],
        "credit_cents": credit,
        "amount_due_cents": line["charge_cents"] - credit,
    }


def handle(request):
    command = request.get("command")
    if command == "ping":
        return {"status": "ok", "product": "Meridian Credits"}
    if command == "quote":
        release = request.get("release", "1.0")
        if release != "1.0":
            return {"error": "unsupported_release"}
        return quote_line_1_0(request["line"])
    return {"error": "unknown_command"}


if __name__ == "__main__":
    json.dump(handle(json.load(sys.stdin)), sys.stdout)
    sys.stdout.write("\n")

import json
from pathlib import Path
import subprocess
import sys
import unittest

ROOT = Path(__file__).resolve().parents[1]

LINE = {
    "line_id": "L-1",
    "account_id": "A",
    "subscription_id": "S",
    "service_on": "2026-04-15",
    "charge_cents": 19999,
}


class QuoteTests(unittest.TestCase):
    def check_request(self, request, expected):
        got = subprocess.run([sys.executable, str(ROOT / "main.py")],
                             input=json.dumps(request), text=True, capture_output=True, check=True)
        self.assertEqual(json.loads(got.stdout), expected)

    def test_quote_explicit_release(self):
        self.check_request(
            {"command": "quote", "release": "1.0", "line": dict(LINE)},
            {"release": "1.0", "line_id": "L-1", "credit_cents": 1999, "amount_due_cents": 18000},
        )

    def test_quote_omitted_release_selects_current_agreement(self):
        self.check_request(
            {"command": "quote", "line": dict(LINE)},
            {"release": "1.0", "line_id": "L-1", "credit_cents": 1999, "amount_due_cents": 18000},
        )

    def test_quote_caps_credit_at_2400(self):
        line = dict(LINE, charge_cents=30000)
        self.check_request(
            {"command": "quote", "line": line},
            {"release": "1.0", "line_id": "L-1", "credit_cents": 2400, "amount_due_cents": 27600},
        )

    def test_quote_rounds_credit_down(self):
        line = dict(LINE, charge_cents=15)
        self.check_request(
            {"command": "quote", "line": line},
            {"release": "1.0", "line_id": "L-1", "credit_cents": 1, "amount_due_cents": 14},
        )

    def test_quote_zero_charge(self):
        line = dict(LINE, charge_cents=0)
        self.check_request(
            {"command": "quote", "line": line},
            {"release": "1.0", "line_id": "L-1", "credit_cents": 0, "amount_due_cents": 0},
        )

    def test_quote_unsupported_release(self):
        self.check_request(
            {"command": "quote", "release": "9.9", "line": dict(LINE)},
            {"error": "unsupported_release"},
        )


if __name__ == "__main__":
    unittest.main()
